alter table public.avuhz_human_approvals alter column diagnostic_scope_id drop not null, alter column approved_scope_version drop not null, alter column canonical_scope_digest drop not null, alter column action_set_version drop not null; alter table public.avuhz_human_approvals add column if not exists subject_type text, add column if not exists subject_id uuid, add column if not exists approval_category text, add column if not exists assessment_access_proposal_id uuid, add column if not exists assessment_access_authority_digest text, add column if not exists actor_identity text, add column if not exists actor_organization text, add column if not exists actor_role text; alter table public.avuhz_human_approvals add constraint avuhz_human_approvals_subject_type_check check (subject_type is null or subject_type in ('DIAGNOSTIC_SCOPE','ASSESSMENT_ACCESS_PROPOSAL')), add constraint avuhz_human_approvals_approval_category_check check (approval_category is null or approval_category='ASSESSMENT_ACCESS'), add constraint avuhz_human_approvals_assessment_digest_check check (assessment_access_authority_digest is null or assessment_access_authority_digest ~ '^sha256:[0-9a-f]{64}$'), add constraint avuhz_human_approvals_subject_binding_check check (subject_type is null or (subject_type='DIAGNOSTIC_SCOPE' and subject_id=diagnostic_scope_id and diagnostic_scope_id is not null and approved_scope_version is not null and canonical_scope_digest is not null and action_set_version is not null and assessment_access_proposal_id is null and assessment_access_authority_digest is null and approval_category is null) or (subject_type='ASSESSMENT_ACCESS_PROPOSAL' and subject_id=assessment_access_proposal_id and assessment_access_proposal_id is not null and assessment_access_authority_digest is not null and approval_category='ASSESSMENT_ACCESS' and diagnostic_scope_id is null and approved_scope_version is null and canonical_scope_digest is null and action_set_version is null and actor_identity is not null and actor_organization is not null and actor_role=approval_role)); alter table public.avuhz_human_approvals add constraint avuhz_human_approvals_tenant_proposal_fkey foreign key (tenant_id,assessment_access_proposal_id) references public.avuhz_assessment_access_proposals (tenant_id,assessment_access_proposal_id); create unique index avuhz_human_approvals_active_assessment_role_key on public.avuhz_human_approvals (tenant_id,assessment_access_proposal_id,assessment_access_authority_digest,approval_role) where subject_type='ASSESSMENT_ACCESS_PROPOSAL' and status='ACTIVE';
